-- ============================================
-- LUMA — Thème 6 : MOYEN 3/3 x4 — Accueillir un nouveau coloc
-- ============================================


update scenarios set content = '{"characters": {"new_roommate": "le nouveau/la nouvelle coloc", "you": "vous"}, "start_node": "n1", "nodes": {"n1": {"speaker": "new_roommate", "text": "Hi! I''m so excited to be moving in, thanks for showing me around.", "text_fr": "Salut ! Je suis trop content d''emménager, merci de me faire visiter.", "choices": [{"text": "Of course! Welcome, let''s start with the kitchen.", "text_fr": "Bien sûr ! Bienvenue, commençons par la cuisine.", "next": "n2"}, {"text": "Welcome! I''ll show you around, starting with your room.", "text_fr": "Bienvenue ! Je te fais visiter, en commençant par ta chambre.", "next": "n2b"}]}, "n2": {"speaker": "you", "text": "This is the kitchen — we usually keep a shared shelf for basics.", "text_fr": "Voici la cuisine — on a un rayon partagé pour les basiques.", "choices": [{"text": "Got it, should I bring my own pots and pans?", "text_fr": "Compris, je devrais amener mes propres casseroles ?", "next": "n3"}, {"text": "Sounds good, any rules about dishes?", "text_fr": "Ça marche, des règles pour la vaisselle ?", "next": "n3"}]}, "n2b": {"speaker": "you", "text": "This will be your room — feel free to decorate it however you like.", "text_fr": "Ça sera ta chambre — décore-la comme tu veux.", "choices": [{"text": "Thanks, it''s a great size! What''s the wifi password by the way?", "text_fr": "Merci, elle est bien grande ! C''est quoi le mot de passe wifi au fait ?", "next": "n3"}]}, "n3": {"speaker": "you", "text": "We ask everyone to wash their dishes within a day, keeps things from piling up.", "text_fr": "On demande à tout le monde de laver sa vaisselle dans la journée, ça évite que ça s''accumule.", "choices": [{"text": "That makes sense, I''ll definitely follow that.", "text_fr": "Ça se comprend, je vais définitivement suivre ça.", "next": "n4"}]}, "n4": {"speaker": "you", "text": "Now, let''s talk house rules — quiet hours are after 10pm on weekdays.", "text_fr": "Maintenant, parlons des règles de la maison — les heures calmes sont après 22h en semaine.", "choices": [{"text": "Got it, I''ll keep that in mind, especially with headphones for music.", "text_fr": "Compris, je vais garder ça en tête, surtout avec des écouteurs pour la musique.", "next": "n5"}, {"text": "Understood — is that flexible on weekends?", "text_fr": "Compris — c''est flexible le week-end ?", "next": "n5b"}]}, "n5": {"speaker": "you", "text": "Exactly, that usually works well for everyone.", "text_fr": "Exactement, ça marche généralement bien pour tout le monde.", "choices": [{"text": "Sounds fair, thanks for explaining.", "text_fr": "Ça semble juste, merci d''avoir expliqué.", "next": "n6"}]}, "n5b": {"speaker": "you", "text": "Yeah, weekends are a bit more relaxed, usually until midnight.", "text_fr": "Ouais, les week-ends sont un peu plus détendus, généralement jusqu''à minuit.", "choices": [{"text": "Good to know, thanks for clarifying.", "text_fr": "Bon à savoir, merci d''avoir clarifié.", "next": "n6"}]}, "n6": {"speaker": "you", "text": "One last thing — we have a group chat for anything important, I''ll add you now.", "text_fr": "Une dernière chose — on a un groupe de discussion pour tout ce qui est important, je t''ajoute maintenant.", "choices": [{"text": "Perfect, that''ll make communication so much easier.", "text_fr": "Parfait, ça va rendre la communication bien plus facile.", "next": "n7"}]}, "n7": {"speaker": "new_roommate", "text": "This all sounds great, I already feel welcome here.", "text_fr": "Tout ça a l''air super, je me sens déjà bienvenu ici.", "choices": [{"text": "We''re really glad to have you! Let us know if you need anything.", "text_fr": "On est vraiment contents de t''avoir ! Fais-nous signe si t''as besoin de quoi que ce soit.", "next": "end_welcomed"}]}, "end_welcomed": {"speaker": "new_roommate", "text": "Thank you, I can already tell this is going to be a great living situation.", "text_fr": "Merci, je peux déjà dire que ça va être une super situation de vie.", "end": true, "ending_label": "Nouveau coloc accueilli chaleureusement 🏠🎉"}}}'::jsonb, is_playable = true
where title = 'Accueillir un nouveau coloc'
  and theme_id = (select id from scenario_themes where position = 6 and language_id = (select id from languages where code = 'en'));
